function base(title: string, body: string, script: string) {
  return `<!doctype html><html lang="el"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Buy Local Sparta development build"><title>${title}</title><style>${sharedStyles}</style></head><body><a class="skipLink" href="#main-content">Μετάβαση στο κύριο περιεχόμενο</a>${body}<script>${script}</script></body></html>`;
}

const commonJs = `
const state={principal:null,csrf:null};
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,options={}){const headers={'content-type':'application/json',...(options.headers||{})};if(state.csrf&&options.method&&options.method!=='GET')headers['x-csrf-token']=state.csrf;const r=await fetch(path,{...options,headers});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||('HTTP '+r.status));return data}
async function whoami(){const m=await api('/api/auth/me');state.principal=m.principal||null;state.csrf=m.principal?.csrfToken||null;return m}
async function doLogin(email,password){const r=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email,password})});state.principal=r.principal;state.csrf=r.principal.csrfToken;return r}
async function doLogout(){await api('/api/auth/logout',{method:'POST',body:'{}'});state.principal=null;state.csrf=null;location.reload()}
function moneyFmt(minor){return new Intl.NumberFormat('el-GR',{style:'currency',currency:'EUR'}).format((minor||0)/100)}
function applyA11y(root=document){root.querySelectorAll('.formRow').forEach(function(row){const label=row.querySelector('label');const controls=Array.from(row.querySelectorAll('input,select,textarea'));if(!label||!controls.length)return;const text=(label.textContent||'Πεδίο').trim();controls.forEach(function(control,index){if(!control.id)control.id='field-'+Math.random().toString(36).slice(2);if(index===0&&!label.htmlFor)label.htmlFor=control.id;if(controls.length>1&&!control.getAttribute('aria-label')&&!control.getAttribute('aria-labelledby'))control.setAttribute('aria-label',text+' '+(index===0?'από':'έως'));});});root.querySelectorAll('.status,.spinner').forEach(function(el){if(!el.getAttribute('role'))el.setAttribute('role',el.classList.contains('error')?'alert':'status');if(!el.getAttribute('aria-live'))el.setAttribute('aria-live',el.classList.contains('error')?'assertive':'polite');});root.querySelectorAll('table').forEach(function(table){table.querySelectorAll('thead th').forEach(function(th){th.setAttribute('scope','col')});if(!table.getAttribute('aria-label')){let prev=table.previousElementSibling;while(prev&&!/^H[1-6]$/.test(prev.tagName))prev=prev.previousElementSibling;if(prev)table.setAttribute('aria-label',(prev.textContent||'Πίνακας').trim());}});}
applyA11y();new MutationObserver(function(){applyA11y()}).observe(document.body,{childList:true,subtree:true});
`;

