async function loadCart(mode){const suffix=mode?'?fulfilmentMode='+encodeURIComponent(mode):'';const d=await api('/api/cart'+suffix);currentCart=d;const target=document.getElementById('cartItems');if(!d.items.length){target.innerHTML='<div class="empty">Το καλάθι είναι άδειο.</div>';document.getElementById('cartFooter').innerHTML='';return}target.innerHTML=d.items.map(function(i){return '<div class="cartItem"><div><b>'+esc(i.title)+'</b>'+(i.specialOffer?'<span class="tag" style="position:static;margin-left:8px">Ιδιωτική προσφορά</span>':i.promotion?'<span class="tag" style="position:static;margin-left:8px">'+esc(i.promotion.name||'Προσφορά')+'</span>':'')+'<br><span class="muted">'+esc(i.localPartner)+' · '+i.quantity+' × '+esc(i.formattedUnitPrice)+'</span></div><button class="btn small removeCartBtn" data-id="'+esc(i.id)+'">×</button></div>'}).join('');target.querySelectorAll('.removeCartBtn').forEach(function(btn){btn.onclick=function(){removeCart(btn.dataset.id)}});const modeOptions=['pickup','local_delivery','shipping'].map(function(value){const label=value==='pickup'?'Παραλαβή από κατάστημα':value==='local_delivery'?'Τοπική παράδοση':'Αποστολή στην Ελλάδα';return '<option value="'+value+'" '+(d.fulfilmentMode===value?'selected':'')+'>'+label+'</option>'}).join('');const quotes=(d.deliveryQuotes||[]).map(function(q){return '<div class="muted" style="font-size:12px">'+esc(q.vendorId)+' · '+esc(q.reason)+' · '+moneyFmt(q.customerCharge.minor)+'</div>'}).join('');const issues=(d.deliveryIssues||[]).map(function(x){return '<div class="status error">'+esc(x.reason)+' · '+esc(x.vendorId)+' · '+esc(x.postcode)+'</div>'}).join('')+(d.commerceIssues||[]).map(function(x){return '<div class="status error">'+esc(x.message||x.code)+' · '+esc(x.title)+'</div>'}).join('');const compat=(d.compatibilityRequirements||[]).map(function(x){return '<label class="notice" style="display:block;margin:8px 0"><input type="checkbox" class="compatConfirm" aria-label="Επιβεβαίωση συμβατότητας για '+esc(x.title)+'" data-id="'+esc(x.canonicalVariantId)+'"> <b>Επιβεβαιώνω τη συμβατότητα</b> · '+esc(x.title)+'<br><span class="muted">'+esc(x.message||'')+' · Αν δεν είσαι βέβαιος, χρησιμοποίησε «Ρώτησε» πριν αγοράσεις.</span></label>'}).join('');const couponUi='<div class="formRow"><label>Κωδικός προσφοράς</label><div class="actions" style="margin-top:0"><input id="couponCode" value="'+esc(d.couponCode||'')+'" placeholder="π.χ. LOCAL10" style="flex:1"><button class="btn small" id="applyCouponBtn">Εφαρμογή</button>'+(d.couponCode?'<button class="btn small" id="clearCouponBtn">Αφαίρεση</button>':'')+'</div>'+(d.couponIssue?'<div class="status error">'+esc(d.couponIssue)+'</div>':d.coupon?'<div class="status ok">'+esc(d.coupon.code)+' · έκπτωση '+esc(d.formattedDiscount)+'</div>':'')+'</div>';document.getElementById('cartFooter').innerHTML='<div class="formRow"><label>Τρόπος παραλαβής / παράδοσης</label><select id="cartMode">'+modeOptions+'</select></div>'+issues+compat+quotes+couponUi+'<div class="cartItem"><span>Προϊόντα</span><b>'+esc(d.formattedMerchandiseSubtotal)+'</b></div><div class="cartItem"><span>Παράδοση</span><b>'+esc(d.formattedDeliveryCharge)+'</b></div>'+(d.discount?.minor>0?'<div class="cartItem"><span>Έκπτωση</span><b>−'+esc(d.formattedDiscount)+'</b></div>':'')+'<div class="cartTotal"><span>Σύνολο</span><span>'+esc(d.formattedTotal)+'</span></div><button class="btn primary" id="checkoutBtn" '+(d.checkoutBlocked?'disabled aria-disabled="true"':'')+'>'+(d.checkoutBlocked?'Η επιλεγμένη παράδοση δεν καλύπτεται':'Ένα checkout · μία πληρωμή')+'</button>';document.getElementById('cartMode').onchange=function(e){changeFulfilment(e.target.value)};document.getElementById('applyCouponBtn').onclick=applyCoupon;if(document.getElementById('clearCouponBtn'))document.getElementById('clearCouponBtn').onclick=clearCoupon;if(!d.checkoutBlocked)document.getElementById('checkoutBtn').onclick=checkout}
async function applyCoupon(){try{const code=document.getElementById('couponCode').value;await api('/api/cart/coupon',{method:'POST',body:JSON.stringify({code:code})});await loadCart()}catch(e){alert(e.message)}}
