async function sendAsk(){try{if(!state.principal)throw new Error('Συνδέσου πρώτα.');const d=await api('/api/ask-local',{method:'POST',body:JSON.stringify({canonicalVariantId:document.getElementById('askProduct').value,sourceUrl:document.getElementById('askUrl').value,need:document.getElementById('askNeed').value,quantity:1,postcode:'23100'})});const s=document.getElementById('askStatus');s.className='status ok';s.textContent='Ιδιωτικό αίτημα '+d.request.id+' ανατέθηκε στο '+(d.assignedShop||d.request.assignedVendorId)+'. SLA έως '+new Date(d.request.responseDueAt).toLocaleString('el-GR');await loadAccountHub()}catch(e){const s=document.getElementById('askStatus');s.className='status error';s.textContent=e.message}}
