function renderReturns(d,recalls){const rows=d.returns||[];document.getElementById('returnsTable').innerHTML=rows.length?'<table><thead><tr><th>Return</th><th>Eligibility</th><th>RMA / custody</th><th>Status / remedy</th><th>Platform action</th></tr></thead><tbody>'+rows.slice().reverse().map(function(r){let action='—';if(r.status==='requested')action='<button class="btn small" onclick="approveReturn(&quot;'+esc(r.id)+'&quot;)">Approve</button>';else if((r.status==='approved'||r.status==='inspection_required')&&!r.authorization)action='<button class="btn small" onclick="authorizeReturn(&quot;'+esc(r.id)+'&quot;)">Issue RMA</button>';else if(r.status==='received')action='<button class="btn small" onclick="inspectReturn(&quot;'+esc(r.id)+'&quot;)">Inspect</button>';else if(r.status==='inspected')action='<button class="btn primary small" onclick="approveRemedy(&quot;'+esc(r.id)+'&quot;)">Approve remedy</button>';else if(r.status==='remedy_approved'&&r.approvedRemedy==='refund')action='<button class="btn primary small" onclick="refundReturn(&quot;'+esc(r.id)+'&quot;,&quot;'+esc(r.disposition||'blocked')+'&quot;)">Execute refund</button>';else if(r.status==='remedy_approved'&&r.approvedRemedy==='price_reduction')action='<button class="btn primary small" onclick="executePriceReduction(&quot;'+esc(r.id)+'&quot;)">Execute price reduction</button>';return '<tr><td><b>'+esc(r.id)+'</b><br><span class="muted">'+esc(r.reason)+' · qty '+r.quantity+'</span></td><td>'+esc(r.eligibility?.state||'—')+'<br><span class="muted">'+esc(r.eligibility?.basis||'')+'</span></td><td>'+(r.authorization?'<b>'+esc(r.authorization.rmaCode)+'</b><br><span class="muted">'+esc(r.authorization.destinationType)+' · '+esc(r.authorization.returnCostPayer)+'</span>':'—')+'<br><span class="muted">custody '+(r.custody||[]).length+' events</span></td><td>'+esc(r.status)+'<br><span class="muted">'+esc(r.approvedRemedy||r.requestedRemedy)+'</span></td><td>'+action+'</td></tr>'}).join('')+'</tbody></table>':'<div class="empty">No return cases.</div>';const recallRows=(recalls&&recalls.recalls)||[];document.getElementById('recallsTable').innerHTML=recallRows.length?'<table><thead><tr><th>Notice</th><th>Order</th><th>Affected qty</th><th>Status</th><th>Return</th></tr></thead><tbody>'+recallRows.slice().reverse().map(function(x){return '<tr><td>'+esc(x.noticeId)+'</td><td>'+esc(x.orderId)+'</td><td>'+x.affectedQuantity+'</td><td>'+esc(x.status)+'</td><td>'+esc(x.returnId||'—')+'</td></tr>'}).join('')+'</tbody></table>':'<div class="empty">No affected-customer recall cases.</div>'}
