function renderContent(d){const pages=d.pages||[],stories=d.stories||[],collections=d.collections||[],redirects=d.redirects||[];const published=pages.filter(function(p){return p.status==='published'}).length;const pendingStories=stories.filter(function(st){return st.status==='vendor_review'||st.status==='approved'}).length;document.getElementById('contentSummary').innerHTML='<div class="kpi"><span>Pages</span><b>'+pages.length+'</b></div><div class="kpi"><span>Published</span><b>'+published+'</b></div><div class="kpi"><span>Stories awaiting workflow</span><b>'+pendingStories+'</b></div><div class="kpi"><span>Sitemap URLs</span><b>'+((d.sitemapEntries||[]).length)+'</b></div>';document.getElementById('contentPages').innerHTML=pages.length?'<table><thead><tr><th>Page</th><th>Type</th><th>Status</th><th>Revision</th><th>Action</th></tr></thead><tbody>'+pages.map(function(p){const tr=(p.translations||[]).find(function(x){return x.locale==='el'})||(p.translations||[])[0];let action=p.status==='published'?'<button class="btn small cmsArchive" data-id="'+esc(p.id)+'">Archive</button>':'<button class="btn primary small cmsPublish" data-id="'+esc(p.id)+'">Publish</button>';return '<tr><td><b>/'+esc(p.slug)+'</b><br><span class="muted">'+esc(tr?.title||'Untitled')+'</span></td><td>'+esc(p.pageType)+'</td><td>'+esc(p.status)+'</td><td>v'+p.version+'</td><td>'+action+'</td></tr>'}).join('')+'</tbody></table>':'<div class="empty">No CMS pages.</div>';document.getElementById('contentStories').innerHTML=stories.length?'<table><thead><tr><th>Story</th><th>Vendor</th><th>Status</th><th>Action</th></tr></thead><tbody>'+stories.map(function(st){const action=st.status==='approved'?'<button class="btn primary small storyPublish" data-id="'+esc(st.id)+'">Publish</button>':'—';return '<tr><td><b>'+esc(st.title)+'</b><br><span class="muted">/'+esc(st.slug)+'</span></td><td>'+esc(st.vendorId)+'</td><td>'+esc(st.status)+'</td><td>'+action+'</td></tr>'}).join('')+'</tbody></table>':'<div class="empty">No merchant stories.</div>';document.getElementById('contentCollections').innerHTML=collections.length?'<table><thead><tr><th>Collection</th><th>Status</th><th>Products</th><th>Action</th></tr></thead><tbody>'+collections.map(function(c){const action=c.status==='published'?'—':'<button class="btn primary small collectionPublish" data-id="'+esc(c.id)+'">Publish</button>';return '<tr><td>'+esc(c.title)+'</td><td>'+esc(c.status)+'</td><td>'+c.canonicalVariantIds.length+'</td><td>'+action+'</td></tr>'}).join('')+'</tbody></table>':'<div class="empty">No collections.</div>';document.getElementById('contentRedirects').innerHTML=redirects.length?'<table><thead><tr><th>From</th><th>To</th><th>Code</th></tr></thead><tbody>'+redirects.map(function(r){return '<tr><td>'+esc(r.fromPath)+'</td><td>'+esc(r.toPath)+'</td><td>'+r.statusCode+'</td></tr>'}).join('')+'</tbody></table>':'<div class="empty">No redirects.</div>';document.querySelectorAll('.cmsPublish').forEach(function(b){b.onclick=function(){publishCmsPage(b.dataset.id)}});document.querySelectorAll('.cmsArchive').forEach(function(b){b.onclick=function(){archiveCmsPage(b.dataset.id)}});document.querySelectorAll('.storyPublish').forEach(function(b){b.onclick=function(){publishCmsStory(b.dataset.id)}});document.querySelectorAll('.collectionPublish').forEach(function(b){b.onclick=function(){publishCmsCollection(b.dataset.id)}})}
async function createCmsPage(){const slug=prompt('Page slug (blank = homepage)','local-guide');if(slug===null)return;const title=prompt('Greek page title','Οδηγός τοπικών αγορών');if(!title)return;const pageBody=prompt('Greek page body','Ανακάλυψε καταστήματα, ανθρώπους και προϊόντα της Σπάρτης.');try{await api('/api/admin/content/pages',{method:'POST',body:JSON.stringify({slug:slug,title:title,body:pageBody,pageType:slug==='sparta'?'local_landing':'standard'})});await render()}catch(e){alert(e.message)}}
